size_t rx_next_n(rx_iter *it, ptrdiff_t (*capture_spans)[2], size_t k)
{
    const unsigned char *s;
    size_t n, lo, i = 0;
    if (__builtin_expect(!capture_spans, 0)) {
        while (i < k && rx__one_local(it)) ++i;
        return i;
    }
    if (k == 0) return 0;
    if (__builtin_expect(it->hdr != PCREC_ITER_BOUND, 0))
        if (!rx__enter(it)) return 0;
    s = it->s;
    n = it->n;
    lo = it->lo;
    while (i < k && rx__one(it, s, n, &lo, capture_spans + i * RX_NCAPS))
        ++i;
    it->lo = lo;
    return i;
}

